function missionMatches(mission,trip){if(mission.kind==='company')return canonicalCompanyName(trip.company,trip.companyCode)===canonicalCompanyName(mission.company,mission.companyCode);if(mission.kind==='city'||mission.kind==='origin')return (mission.cities||[mission.city]).includes(trip.from);if(mission.kind==='destination')return (mission.cities||[mission.city]).includes(trip.to);return false}
