function riceSeedCitySection(city=state.city){const agriculture=ensureAgricultureState(),seller=RICE_SEED_CITIES.includes(city),owned=Object.values(agriculture.farms).some(farm=>farm.owned);if(!seller)return'';return'<section class="rice-seed-store"><div><span>INSUMOS AGRÍCOLAS · '+escapeHTML(city.toUpperCase())+'</span><h2>Sementes de arroz</h2><p>Compre sacos de sementes e leve-os a qualquer terreno agrícola próprio. Cada terreno comporta até 5 sacos aguardando plantio.</p></div><strong>'+money(RICE_SEED_PRICE)+'</strong>'+(owned?'<button data-city-buy-rice-seed '+(!state.trip&&state.balance>=RICE_SEED_PRICE?'':'disabled')+'>COMPRAR 1 SACO</button>':'<button data-city-rice-farm>CONHECER TERRENOS AGRÍCOLAS</button>')+'</section>'}
function ensureAgricultureState(){if(!state)return{farms:{},carriedSeeds:0};if(!state.agriculture||typeof state.agriculture!=='object'||Array.isArray(state.agriculture))state.agriculture={};const agriculture=state.agriculture;if(!agriculture.farms||typeof agriculture.farms!=='object'||Array.isArray(agriculture.farms)){agriculture.farms={};if(agriculture.owned)agriculture.farms['Guaratinguetá']={owned:true,boughtAt:Number(agriculture.boughtAt)||Date.now(),seeds:Number(agriculture.seedAtFarm)||0,stock:[],plantedAt:Number(agriculture.plantedAt)||0,harvestAt:Number(agriculture.harvestAt)||0}}agriculture.carriedSeeds=Math.max(0,Math.floor(Number(agriculture.carriedSeeds)||(agriculture.seedPurchased?1:0)));Object.keys(RICE_FARM_SITES).forEach(city=>{const farm=agriculture.farms[city];if(!farm)return;farm.owned=Boolean(farm.owned);farm.seeds=Math.max(0,Math.min(5,Math.floor(Number(farm.seeds)||0)));farm.stock=Array.isArray(farm.stock)?farm.stock:[];farm.plantedAt=Number(farm.plantedAt)||0;farm.harvestAt=Number(farm.harvestAt)||0});return agriculture}
function farmCapacity(){return hasSkill('farmPalletSpace')?2:1}function riceGrowDuration(){return RICE_GROW_MS-(hasSkill('fasterRiceGrowing')?30*60*1000:0)}
function riceRoute(origin,destination){const direct=(routes[origin]||[]).find(route=>route.to===destination);if(direct)return{km:direct.km,ferry:Boolean(direct.ferry)};const a=cities[origin],b=cities[destination];if(!a||!b)return null;const rad=value=>value*Math.PI/180,dLat=rad(b.lat-a.lat),dLng=rad(b.lng-a.lng),h=Math.sin(dLat/2)**2+Math.cos(rad(a.lat))*Math.cos(rad(b.lat))*Math.sin(dLng/2)**2;return{km:Math.max(8,Math.round(6371*2*Math.atan2(Math.sqrt(h),Math.sqrt(1-h))*1.22)),ferry:false}}
