async function publishRiceCall(city,pallet){if(!user||!pallet)return;const route=riceRoute(city,pallet.destination);try{await publishProductionCall(pallet.id,{id:pallet.id,status:'available',ownerId:user.uid,ownerName:user.displayName||'Motorista',ownerCompany:state.companyName||'Produtor independente',origin:city,destination:pallet.destination,km:route?.km||0,ferry:Boolean(route?.ferry),product:'player-rice',gross:2500,createdAt:serverTimestamp(),createdAtMs:pallet.producedAt||Date.now()})}catch(error){console.warn('Não foi possível publicar a chamada agrícola:',error.code||error.message)}}
