function buySmallFarm(city=farmViewCity){const agriculture=ensureAgricultureState(),site=RICE_FARM_SITES[city];if(!site||agriculture.farms[city]?.owned)return;if(!hasSkill('smallFarm')){toast('Libere primeiro a habilidade Comprar terreno pequeno para agricultura.');return}if(!atProductionSite('player-rice',city)){toast('Siga o caminho até o terreno de '+city+' para comprar.');return}if(state.balance<FARM_BUY_PRICE){toast('Saldo insuficiente. O terreno custa '+money(FARM_BUY_PRICE)+'.');return}state.balance-=FARM_BUY_PRICE;agriculture.farms[city]={owned:true,boughtAt:Date.now(),seeds:0,stock:[],plantedAt:Date.now(),harvestAt:Date.now()+riceGrowDuration()};addLedger('debit',FARM_BUY_PRICE,'Compra de terreno agrícola','Pequeno terreno para plantação de arroz próximo de '+city+'.',Date.now(),'small-rice-farm-'+city);save();toast('Terreno agrícola em '+city+' comprado por '+money(FARM_BUY_PRICE)+'.');agriculturePage()}
function buyRiceSeed(){const agriculture=ensureAgricultureState();if(state.trip||!RICE_SEED_CITIES.includes(state.city)||!Object.values(agriculture.farms).some(farm=>farm.owned))return;if(state.balance<RICE_SEED_PRICE){toast('Saldo insuficiente para comprar o saco de sementes.');return}state.balance-=RICE_SEED_PRICE;agriculture.carriedSeeds++;addLedger('debit',RICE_SEED_PRICE,'Sementes de arroz','Saco comprado em '+state.city+'.',Date.now(),'rice-seed-'+Date.now());save();toast('Saco de sementes comprado. Leve-o até um terreno próprio.');if(location.hash==='#agricultura')agriculturePage();else cityPage(state.city)}
function depositRiceSeeds(city=farmViewCity){const agriculture=ensureAgricultureState(),farm=agriculture.farms[city];if(!farm?.owned||state.trip||state.city!==city||agriculture.carriedSeeds<1)return;const amount=Math.min(agriculture.carriedSeeds,5-farm.seeds);if(amount<1){toast('Este terreno já possui 5 sacos aguardando plantio.');return}agriculture.carriedSeeds-=amount;farm.seeds+=amount;beginFarmPlanting(farm);save();toast(amount+' saco'+(amount===1?'':'s')+' entregue'+(amount===1?'':'s')+' ao terreno. O plantio é automático.');agriculturePage()}
function reconcileOwnFarmCalls(){if(!user)return;const available=id=>!playerCalls.some(call=>call.id===id&&call.status!=='available'),agriculture=ensureAgricultureState(),pharma=ensurePharmaceuticalState(),wineries=ensureWineState();let changed=false;Object.entries(agriculture.farms).forEach(([city,farm])=>{const before=farm.stock.length;farm.stock=farm.stock.filter(pallet=>available(pallet.id));if(farm.stock.length!==before){changed=true;advanceFarm(city,farm)}});Object.values(pharma.factories).forEach(factory=>{if(!factory?.stock)return;const before=factory.stock.length;factory.stock=factory.stock.filter(pallet=>available(pallet.id));if(factory.stock.length!==before)changed=true});const winery=wineries['São Roque'];if(winery?.stock){const before=winery.stock.length;winery.stock=winery.stock.filter(pallet=>available(pallet.id));if(winery.stock.length!==before)changed=true}const pasta=ensurePastaFactoryState();if(pasta.stock.length){const before=pasta.stock.length;pasta.stock=pasta.stock.filter(pallet=>{const call=playerCalls.find(item=>item.id===pallet.id);if(call&&call.status!=='available')pasta.slotFreedAt=Number(call.claimedAtMs)||Date.now();return available(pallet.id)});if(pasta.stock.length!==before){changed=true;advancePastaFactory()}}if(changed)save()}
function watchPlayerCalls(){playerCallsStop?.();playerCalls=[];if(!user)return;playerCallsStop=onSnapshot(collection(db,'playerCalls'),snapshot=>{playerCalls=snapshot.docs.map(item=>({id:item.id,...item.data()})).sort((a,b)=>(Number(a.createdAtMs)||0)-(Number(b.createdAtMs)||0));if(!productionBusy)reconcileOwnFarmCalls();if(location.hash==='#chamadas')playerCallsPage();recoverClaimedProduction();retryProductionPublications();if(!productionBusy)refreshProductionPage()},error=>console.warn('Chamadas dos jogadores indisponíveis:',error.code||error.message))}
async function claimPlayerCall(id,button){
 const call=playerCalls.find(c=>c.id===id);if(productionBusy||!call||!atProductionSite(call.product,call.origin))return;
 if(truckPalletCount()>=truckPalletLimit()){toast('Seu caminhão está sem espaço.');return}
 productionBusy=true;if(button){button.disabled=true;button.textContent='RETIRANDO...'}
 try{await syncProgress();const claimed=await runTransaction(db,async tx=>{const ref=doc(db,'playerCalls',id),pRef=doc(db,'progress',user.uid),snap=await tx.get(ref),pSnap=await tx.get(pRef);
 if(!snap.exists()||snap.data().status!=='available')throw Error('call-unavailable');
 const saved=pSnap.data(),cargo=saved.truckPallets||[];if(cargo.length>=truckPalletLimit())throw Error('capacity');
 const next={...snap.data(),id,status:'claimed',claimedBy:user.uid,claimedByName:user.displayName||'Motorista',claimedAtMs:Date.now(),fuelAllowance:fuelCostFor(snap.data().km)};
 tx.update(ref,{status:next.status,claimedBy:next.claimedBy,claimedByName:next.claimedByName,claimedAt:serverTimestamp(),claimedAtMs:next.claimedAtMs,fuelAllowance:next.fuelAllowance});
 tx.update(pRef,{truckPallets:[...cargo,productionCargo(next)],savedAt:Date.now()});return next});
 if(!state.truckPallets.some(p=>p.id===id))state.truckPallets.push(productionCargo(claimed));
 playerCalls=playerCalls.map(c=>c.id===id?claimed:c);reconcileOwnFarmCalls();save();toast('Palete retirado para o caminhão. Entregue em '+claimed.destination+'.');location.hash='mapa';
 }catch(error){toast(error.message==='call-unavailable'?'Outro jogador já retirou este palete.':'Retirada não concluída. Verifique a conexão e tente novamente.');if(button){button.disabled=false;button.textContent='RETIRAR PALETE'}}finally{productionBusy=false}
}
async function settlePlayerCallDelivery(trip){if(!trip?.playerCall||trip.playerCallSettled)return;trip.playerCallSettled=true;try{await setDoc(doc(db,'playerCalls',trip.playerCallId),{status:'delivered',deliveredBy:user.uid,deliveredByName:user.displayName||'Motorista',deliveredAt:serverTimestamp(),deliveredAtMs:Date.now()},{merge:true});if(trip.ownerId!==user.uid){const ownerNet=Math.max(0,(Number(trip.gross)||2500)-500-(Number(trip.fuelAllowance)||0)),earningId=trip.playerCallId+'-'+trip.ownerId;await setDoc(doc(db,'farmEarnings',earningId),{id:earningId,ownerId:trip.ownerId,courierId:user.uid,callId:trip.playerCallId,amount:ownerNet,courierName:user.displayName||'Motorista',destination:trip.to,product:trip.product||'rice',claimed:false,createdAt:serverTimestamp(),createdAtMs:Date.now()},{merge:false})}}catch(error){trip.playerCallSettled=false;console.warn('Liquidação agrícola pendente:',error.code||error.message)}}
function watchFarmEarnings(){farmEarningsStop?.();if(!user)return;farmEarningsStop=onSnapshot(query(collection(db,'farmEarnings'),where('ownerId','==',user.uid)),async snapshot=>{for(const item of snapshot.docs)if(!item.data().claimed)await creditProductionEarning(item.ref)},error=>console.warn('Repasses indisponíveis:',error))}
const productionEarningsPending=new Set();
async function creditProductionEarning(ref){
 if(productionBusy||productionEarningsPending.has(ref.id))return;productionEarningsPending.add(ref.id);productionBusy=true;
 try{await syncProgress();const result=await runTransaction(db,async tx=>{const snap=await tx.get(ref),pRef=doc(db,'progress',user.uid),pSnap=await tx.get(pRef);if(!snap.exists()||snap.data().claimed)return null;const e=snap.data(),saved=pSnap.data(),at=Date.now(),amount=Number(e.amount)||0,next={...saved,balance:saved.balance+amount,savedAt:at,ledger:[{id:'farm-earning-'+e.callId,ref:'farm-earning-'+e.callId,type:'credit',amount,title:'Venda de produção',details:'Entrega por '+e.courierName+' em '+e.destination,at},...(saved.ledger||[])]};tx.update(ref,{claimed:true,claimedAt:serverTimestamp()});tx.set(pRef,next);return next});if(result){state={...state,...result};localStorage.setItem(key(),JSON.stringify(state));chrome();syncPresence();toast('Pagamento de produção recebido.')}}catch(error){console.warn('Repasse pendente:',error)}finally{productionEarningsPending.delete(ref.id);productionBusy=false}
}
function playerCallsPage(){const available=playerCalls.filter(call=>call.status==='available'),cards=available.map(call=>{const here=atProductionSite(call.product,call.origin),own=call.ownerId===user.uid,fuel=fuelCostFor(call.km),gross=Number(call.gross)||(call.product==='paracetamol'?4000:call.product==='wine'?3500:call.product==='pasta'?1500:2500),driverPay=own?gross:500+fuel,image=call.product==='paracetamol'?'assets/items/paracetamol-tablets-pallet.png':call.product==='wine'?'assets/items/wine-pallet.png':call.product==='pasta'?'assets/items/pasta-pallet.png':'assets/items/player-rice-pallet.png';return'<article class="player-call-card"><img src="'+image+'" alt="Palete de produção"><div><span>'+escapeHTML(own?'SUA PRODUÇÃO':'EMPRESA DE JOGADOR')+'</span><h2>'+escapeHTML(productionSite(call.product,call.origin).name)+'</h2><small>Dono: '+escapeHTML(call.ownerName)+' · '+escapeHTML(call.ownerCompany||'Produtor independente')+'</small><p>'+escapeHTML(call.origin)+' → '+escapeHTML(call.destination)+' · '+call.km+' km</p><small>Coleta em '+escapeHTML(call.origin)+'</small><a data-production-origin="'+escapeHTML(call.origin)+'" class="production-link" href="#'+productionSite(call.product,call.origin).page+'">VER CAMINHO ATÉ A EMPRESA →</a></div><aside><span>VOCÊ RECEBE</span><b>'+money(driverPay)+'</b><small>'+(own?'Venda integral do seu palete':'R$ 500,00 + '+money(fuel)+' de combustível')+'</small><button data-player-call="'+escapeHTML(call.id)+'" '+(here&&!state.trip?'':'disabled')+'>'+(here?'PEGAR ENCOMENDA':'VÁ ATÉ '+escapeHTML(call.origin.toUpperCase()))+'</button></aside></article>'}).join('');$('#view').innerHTML=heading('FRETES DA COMUNIDADE','Chamadas dos Jogadores','Transporte os paletes produzidos nas empresas dos jogadores.')+'<section class="player-call-summary"><article><span>CHAMADAS DISPONÍVEIS</span><b>'+available.length+'</b></article><article><span>PAGAMENTO DO MOTORISTA</span><b>'+money(500)+'</b><small>Mais o combustível da rota</small></article><article><span>VALOR DO PALETE</span><b>'+money(2500)+'</b></article></section><section class="player-call-list">'+(cards||'<div class="career-warehouse-empty"><span>♧</span><h2>Nenhuma chamada disponível</h2><p>Novas chamadas aparecem automaticamente quando os paletes das empresas entram no estoque.</p></div>')+'</section>';document.querySelectorAll('[data-player-call]').forEach(button=>button.onclick=()=>claimPlayerCall(button.dataset.playerCall,button));document.querySelectorAll('[data-production-origin]').forEach(link=>link.onclick=()=>{farmViewCity=link.dataset.productionOrigin})}
function agriculturePage(){advanceAllFarms();const agriculture=ensureAgricultureState(),sites=Object.keys(RICE_FARM_SITES),selected=RICE_FARM_SITES[farmViewCity]?farmViewCity:sites[0],farm=agriculture.farms[selected],here=atProductionSite('player-rice',selected),capacity=farmCapacity(),growing=farm?.plantedAt&&Date.now()<farm.harvestAt,remaining=growing?farm.harvestAt-Date.now():0,siteTabs='<nav class="page-tabs farm-site-tabs">'+sites.map(city=>'<button data-farm-site="'+escapeHTML(city)+'" class="'+(city===selected?'active':'')+'">'+escapeHTML(city.toUpperCase())+'</button>').join('')+'</nav>',owned=farm?.owned,action=!owned?'<section class="farm-action-card"><span>'+(hasSkill('smallFarm')?'TERRENO DISPONÍVEL':'LICENÇA NECESSÁRIA')+'</span><h2>Pequeno terreno para arroz</h2><p>Ao comprar, o cultivo automático de seis horas começa imediatamente.</p><strong>'+money(FARM_BUY_PRICE)+'</strong>'+(hasSkill('smallFarm')?'<button data-buy-farm '+(here&&state.balance>=FARM_BUY_PRICE?'':'disabled')+'>COMPRAR TERRENO</button>':'<button data-open-farm-skill>LIBERAR HABILIDADE · 20 PONTOS</button>')+'<small>'+(here?'Você está no local da compra.':'Vá até '+escapeHTML(selected)+' para realizar a compra.')+'</small></section>':'<section class="farm-management"><header><div><span>PRODUÇÃO AUTOMÁTICA</span><h2>Terreno de '+escapeHTML(selected)+'</h2><p>Nenhuma semente é necessária. Cada ciclo de seis horas produz um palete com destino paulista sorteado.</p></div><b>'+farm.stock.length+' / '+capacity+' PALETES</b></header><div class="farm-stats"><article><span>STATUS</span><b>'+(growing?'CULTIVANDO':'AGUARDANDO ESPAÇO')+'</b></article><article><span>TEMPO POR PALETE</span><b>'+((riceGrowDuration()/3600000).toFixed(1).replace('.',','))+' H'+'</b></article><article><span>ESTOQUE</span><b>'+farm.stock.length+' / '+capacity+'</b></article></div>'+(growing?'<div class="farm-timer"><span>PRÓXIMO PALETE</span><b id="rice-grow-time">'+formatTime(remaining)+'</b><small>A produção continua mesmo com o jogo fechado.</small></div>':'<div class="farm-timer"><span>PRODUÇÃO PAUSADA</span><b>ESTOQUE CHEIO</b><small>Retire um palete para iniciar automaticamente outro ciclo.</small></div>')+'<div class="farm-stock">'+Array.from({length:capacity},(_,index)=>{const pallet=farm.stock[index];return'<article class="pallet-slot '+(pallet?'occupied':'empty')+'">'+(pallet?'<img src="assets/items/player-rice-pallet.png" alt="Palete de arroz"><div><b>PALETE DE ARROZ</b><small>Destino: '+escapeHTML(pallet.destination)+'</small></div>':'<div><b>ESPAÇO VAZIO</b><small>Produção em andamento</small></div>')+'</article>'}).join('')+'</div></section>';$('#view').innerHTML=heading('PRODUÇÃO DO JOGADOR','Agricultura','Produção automática de arroz em ciclos de seis horas.')+siteTabs+'<section class="farm-hero"><img src="assets/properties/small-rice-farm.png" alt="Pequeno terreno de arroz"><div><span>'+(!owned?'TERRENO À VENDA':growing?'PLANTAÇÃO EM CRESCIMENTO':'PROPRIEDADE AGRÍCOLA')+'</span><h2>Plantação de arroz</h2><p>Próximo de '+escapeHTML(selected)+', SP</p></div></section>'+action;document.querySelectorAll('[data-farm-site]').forEach(button=>button.onclick=()=>{farmViewCity=button.dataset.farmSite;agriculturePage()});document.querySelector('[data-open-farm-skill]')?.addEventListener('click',()=>{skillTab='agriculture';location.hash='habilidades'});document.querySelector('[data-buy-farm]')?.addEventListener('click',()=>buySmallFarm(selected));renderProductionAccess('player-rice',selected);if(growing)mapTimer=setInterval(()=>{const node=$('#rice-grow-time'),left=Math.max(0,farm.harvestAt-Date.now());if(node)node.textContent=formatTime(left);if(left<=0){clearInterval(mapTimer);agriculturePage()}},1000)}function ensurePharmaceuticalState(){if(!state.pharmaceutical||typeof state.pharmaceutical!=='object'||Array.isArray(state.pharmaceutical))state.pharmaceutical={};const pharma=state.pharmaceutical;if(!pharma.factories||typeof pharma.factories!=='object')pharma.factories={};Object.keys(MEDICINE_FACTORY_SITES).forEach(city=>{const factory=pharma.factories[city];if(factory){factory.owned=Boolean(factory.owned);factory.stock=Array.isArray(factory.stock)?factory.stock:[];factory.startedAt=Number(factory.startedAt)||0;factory.readyAt=Number(factory.readyAt)||0}});return pharma}
