function medicineMaterialSection(city){if(city!==medicineMaterialSeller()||!hasSkill('medicineFactory'))return'';return'<section class="rice-seed-store medicine-material-store"><div><span>OFERTA FARMACÊUTICA DO DIA · '+escapeHTML(city.toUpperCase())+'</span><h2>Palete de insumos para paracetamol</h2><p>Paracetamol em pó, amido, celulose, estearato de magnésio e água purificada. A oferta muda à meia-noite.</p></div><strong>'+money(MEDICINE_MATERIAL_PRICE)+'</strong><button data-buy-medicine-material '+(!state.trip&&state.balance>=MEDICINE_MATERIAL_PRICE&&truckPalletCount()<truckPalletLimit()?'':'disabled')+'>COMPRAR PALETE</button></section>'}
function buyMedicineMaterial(){if(!hasSkill('medicineFactory')||state.trip||state.city!==medicineMaterialSeller()||state.balance<MEDICINE_MATERIAL_PRICE||truckPalletCount()>=truckPalletLimit())return;state.balance-=MEDICINE_MATERIAL_PRICE;state.truckPallets.push({id:'medin-'+Date.now(),product:'medicine-materials',name:'Insumos para paracetamol',cost:MEDICINE_MATERIAL_PRICE,boughtIn:state.city});addLedger('debit',MEDICINE_MATERIAL_PRICE,'Insumos farmacêuticos','Palete para fabricar 3 paletes de paracetamol.',Date.now(),'medicine-material-'+Date.now());save();toast('Palete de insumos carregado. Leve-o até uma fábrica própria.');cityPage(state.city)}
async function publishMedicineCall(city,pallet){const route=riceRoute(city,pallet.destination);try{await publishProductionCall(pallet.id,{id:pallet.id,status:'available',ownerId:user.uid,ownerName:user.displayName||'Motorista',ownerCompany:state.companyName||'Fábrica farmacêutica',origin:city,destination:pallet.destination,km:route?.km||0,product:'paracetamol',gross:4000,createdAt:serverTimestamp(),createdAtMs:pallet.producedAt})}catch(error){console.warn('Não foi possível publicar o palete farmacêutico:',error.code||error.message)}}
function advanceMedicineFactories(){const pharma=ensurePharmaceuticalState();let changed=false;Object.entries(pharma.factories).forEach(([city,factory])=>{if(factory.owned&&!factory.startedAt){factory.startedAt=Date.now();factory.readyAt=factory.startedAt+MEDICINE_GROW_MS;changed=true}if(factory.owned&&factory.startedAt&&Date.now()>=factory.readyAt){factory.startedAt=Date.now();factory.readyAt=Date.now()+MEDICINE_GROW_MS;for(let n=0;n<3;n++){const id='medicine-'+user.uid+'-'+Date.now()+'-'+n,pallet={id,product:'paracetamol',destination:randomRiceDestination(city,id),origin:city,producedAt:Date.now()};factory.stock.push(pallet);publishMedicineCall(city,pallet)}changed=true}});if(changed)save();return changed}
function buyMedicineFactory(city){const pharma=ensurePharmaceuticalState();if(!hasSkill('medicineFactory')){toast('Libere a licença da Fábrica de Medicamentos.');return}if(!atProductionSite('paracetamol',city)||pharma.factories[city]?.owned)return;if(state.balance<MEDICINE_FACTORY_PRICE){toast('Saldo insuficiente.');return}state.balance-=MEDICINE_FACTORY_PRICE;pharma.factories[city]={owned:true,boughtAt:Date.now(),stock:[],startedAt:Date.now(),readyAt:Date.now()+MEDICINE_GROW_MS};addLedger('debit',MEDICINE_FACTORY_PRICE,'Compra de fábrica de medicamentos','Unidade farmacêutica em '+city+'.',Date.now(),'medicine-factory-'+city);save();pharmaceuticalPage()}
function startMedicineProduction(city){const factory=ensurePharmaceuticalState().factories[city],index=state.truckPallets.findIndex(item=>item.product==='medicine-materials');if(!factory?.owned||factory.startedAt||state.trip||state.city!==city||index<0)return;state.truckPallets.splice(index,1);factory.startedAt=Date.now();factory.readyAt=factory.startedAt+MEDICINE_GROW_MS;save();toast('Fabricação iniciada. Em 6 horas serão produzidos 3 paletes.');pharmaceuticalPage()}
function pharmaceuticalPage(){advanceMedicineFactories();const pharma=ensurePharmaceuticalState(),sites=Object.keys(MEDICINE_FACTORY_SITES),selected=MEDICINE_FACTORY_SITES[farmViewCity]?farmViewCity:sites[0],factory=pharma.factories[selected],here=atProductionSite('paracetamol',selected),growing=factory?.startedAt&&Date.now()<factory.readyAt,remaining=growing?factory.readyAt-Date.now():0,tabs='<nav class="page-tabs">'+sites.map(city=>'<button data-pharma-site="'+city+'" class="'+(city===selected?'active':'')+'">'+city.toUpperCase()+'</button>').join('')+'</nav>',action=!factory?.owned?'<section class="farm-action-card"><span>'+(hasSkill('medicineFactory')?'LOCAL DISPONÍVEL':'LICENÇA NECESSÁRIA')+'</span><h2>Fábrica de Medicamentos</h2><p>Unidade preparada para fabricar comprimidos de paracetamol.</p><strong>'+money(MEDICINE_FACTORY_PRICE)+'</strong><button data-buy-medicine-factory '+(hasSkill('medicineFactory')&&here&&state.balance>=MEDICINE_FACTORY_PRICE?'':'disabled')+'>COMPRAR TERRENO E FÁBRICA</button></section>':'<section class="farm-management"><header><div><span>INDÚSTRIA FARMACÊUTICA</span><h2>Fábrica de '+selected+'</h2><p>A fábrica produz automaticamente 3 paletes de paracetamol a cada ciclo de 6 horas.</p></div><b>'+factory.stock.length+' PALETES PRONTOS</b></header>'+(growing?'<div class="farm-timer"><span>FABRICAÇÃO EM ANDAMENTO</span><b id="medicine-time">'+formatTime(remaining)+'</b></div>':'<button data-start-medicine '+(here&&state.truckPallets.some(item=>item.product==='medicine-materials')?'':'disabled')+'>ENTREGAR INSUMOS E FABRICAR</button>')+'</section>';$('#view').innerHTML=heading('INDÚSTRIA DO JOGADOR','Farmacêutico','Fabrique paracetamol e publique fretes para outros jogadores.')+tabs+'<section class="farm-hero medicine-hero"><img src="assets/properties/small-medicine-factory.png" alt="Fábrica de medicamentos"><div><span>PRODUÇÃO DE PARACETAMOL</span><h2>Fábrica de Medicamentos</h2><p>'+selected+', SP</p></div></section>'+action;document.querySelectorAll('[data-pharma-site]').forEach(button=>button.onclick=()=>{farmViewCity=button.dataset.pharmaSite;pharmaceuticalPage()});document.querySelector('[data-buy-medicine-factory]')?.addEventListener('click',()=>buyMedicineFactory(selected));document.querySelector('[data-start-medicine]')?.addEventListener('click',()=>startMedicineProduction(selected));renderProductionAccess('paracetamol',selected);if(growing)mapTimer=setInterval(()=>{const left=Math.max(0,factory.readyAt-Date.now()),node=$('#medicine-time');if(node)node.textContent=formatTime(left);if(!left){clearInterval(mapTimer);pharmaceuticalPage()}},1000)}
function ensureWineState(){if(!state.wineries||typeof state.wineries!=='object'||Array.isArray(state.wineries))state.wineries={};const winery=state.wineries['São Roque'];if(winery){winery.owned=Boolean(winery.owned);winery.stock=Array.isArray(winery.stock)?winery.stock:[];winery.startedAt=Number(winery.startedAt)||0;winery.readyAt=Number(winery.readyAt)||0}return state.wineries}
async function publishWineCall(pallet){const city='São Roque',route=riceRoute(city,pallet.destination);try{await publishProductionCall(pallet.id,{id:pallet.id,status:'available',ownerId:user.uid,ownerName:user.displayName||'Motorista',ownerCompany:state.companyName||'Vinícola do jogador',origin:city,destination:pallet.destination,km:route?.km||0,product:'wine',gross:3500,createdAt:serverTimestamp(),createdAtMs:pallet.producedAt})}catch(error){console.warn('Não foi possível publicar o palete de vinho:',error.code||error.message)}}
function advanceWineFactories(){const winery=ensureWineState()['São Roque'];if(!winery?.owned)return false;let changed=false;if(!winery.startedAt){winery.startedAt=Date.now();winery.readyAt=winery.startedAt+WINE_GROW_MS;changed=true}if(winery.startedAt&&Date.now()>=winery.readyAt){const cycles=Math.max(1,Math.floor((Date.now()-winery.readyAt)/WINE_GROW_MS)+1);for(let n=0;n<cycles;n++){const id='wine-'+user.uid+'-'+Date.now()+'-'+n,pallet={id,product:'wine',destination:randomRiceDestination('São Roque',id),origin:'São Roque',producedAt:Date.now()};winery.stock.push(pallet);publishWineCall(pallet)}winery.startedAt=winery.readyAt+(cycles-1)*WINE_GROW_MS;winery.readyAt=winery.startedAt+WINE_GROW_MS;changed=true}if(changed)save();return changed}
function buyWineFactory(){const wineries=ensureWineState();if(!hasSkill('wineFactory')){toast('Libere primeiro a Licença para Fábrica de Vinho.');return}if(!atProductionSite('wine','São Roque')||wineries['São Roque']?.owned)return;if(state.balance<WINE_FACTORY_PRICE){toast('Saldo insuficiente. A fábrica custa '+money(WINE_FACTORY_PRICE)+'.');return}state.balance-=WINE_FACTORY_PRICE;wineries['São Roque']={owned:true,boughtAt:Date.now(),stock:[],startedAt:Date.now(),readyAt:Date.now()+WINE_GROW_MS};addLedger('debit',WINE_FACTORY_PRICE,'Compra de fábrica de vinho','Vinícola próxima de São Roque.',Date.now(),'wine-factory-sao-roque');save();toast('Vinícola comprada. O primeiro palete ficará pronto em 6 horas.');wineFactoryPage()}
