function ensurePastaFactoryState(){if(!state.pastaFactory||typeof state.pastaFactory!=='object'||Array.isArray(state.pastaFactory))state.pastaFactory={};const factory=state.pastaFactory;factory.owned=Boolean(factory.owned);factory.stock=Array.isArray(factory.stock)?factory.stock.slice(0,1):[];factory.startedAt=Number(factory.startedAt)||0;factory.readyAt=Number(factory.readyAt)||0;return factory}
async function publishPastaCall(pallet){const route=riceRoute('Campinas',pallet.destination);try{await publishProductionCall(pallet.id,{id:pallet.id,status:'available',ownerId:user.uid,ownerName:user.displayName||'Motorista',ownerCompany:state.companyName||'Fábrica artesanal de massas',origin:'Campinas',destination:pallet.destination,km:route?.km||0,product:'pasta',gross:1500,createdAt:serverTimestamp(),createdAtMs:pallet.producedAt})}catch(error){console.warn('Não foi possível publicar o palete de massas:',error.code||error.message)}}
function advancePastaFactory(){
 const factory=ensurePastaFactoryState();if(!factory.owned)return false;
 const now=Date.now();let changed=false;
 if(!factory.startedAt){factory.startedAt=factory.stock[0]?.producedAt||now;factory.readyAt=factory.startedAt+PASTA_GROW_MS;changed=true}
 if(now>=factory.readyAt&&factory.stock.length<1){
  const producedAt=factory.readyAt,id='pasta-'+user.uid+'-'+producedAt;
  const pallet={id,product:'pasta',destination:randomRiceDestination('Campinas',id),origin:'Campinas',producedAt};
  factory.stock=[pallet];factory.startedAt=Math.max(producedAt,Number(factory.slotFreedAt)||0);factory.readyAt=factory.startedAt+PASTA_GROW_MS;
  delete factory.slotFreedAt;publishPastaCall(pallet);changed=true;
 }
 if(changed)save();return changed;
}
