function finishTrip(){if(!state.trip)return;if(state.trip.playerCall&&!state.trip.playerCallSettled)settlePlayerCallDelivery(state.trip);updateTripFuel(true);const t=state.trip,id=crypto.randomUUID?.()||String(Date.now()),at=Date.now(),condition=t.truckOnTrain?tireCondition(t.truckId||state.truck):applyTireWear(t.totalKm,t.truckId||state.truck),specialBonus=t.specialMission?(Number(t.missionBonus)||500):0,specialSkillPoints=t.specialMission?.2:0;if(t.freeTrip){if(!t.truckOnTrain)state.km+=t.totalKm;state.city=t.to;state.trip=null;state.facility=t.facilityArrival||null;save();clearInterval(mapTimer);toast((t.truckOnTrain?'Transporte Truck-on-Train concluído! Você chegou a ':t.palletTrip?'Transporte de pallets concluído! Você chegou a ':'Viagem livre concluída! Você chegou a ')+t.to+'. Pneus: '+condition.toFixed(1).replace('.',',')+'%.');location.hash=t.facilityArrival?productionSite(t.facilityArrival.product,t.to).page:'cidade/'+encodeURIComponent(t.to);return}state.xp+=t.xp;state.balance+=t.pay+(Number(t.fuelAllowance)||0)+specialBonus;state.deliveries++;state.km+=t.totalKm;state.city=t.to;state.history.unshift({id,from:t.from,to:t.to,company:t.company,cargo:t.cargo,km:t.totalKm,pay:t.pay,at});addLedger('credit',t.pay,'Pagamento de entrega',t.company+' · '+t.from+' → '+t.to+' · '+t.totalKm+' km',at,'delivery-'+id);if(Number(t.fuelAllowance)>0)addLedger('credit',t.fuelAllowance,'Auxílio-combustível da empresa',t.company+' · '+Number(t.fuelUsed||0).toFixed(2).replace('.',',')+' L de diesel S10 · '+t.totalKm+' km',at,'fuel-allowance-'+id);if(specialBonus)addLedger('credit',specialBonus,'Bônus de missão especial',t.company+' · entrega exclusiva concluída em '+t.to+'.',at,'special-mission-'+t.specialMissionId);if(specialSkillPoints)state.missionPoints=Math.round((Number(state.missionPoints)+specialSkillPoints)*100)/100;const missionReward=updateMissions(t),reputationReward=addCompanyReputation(t.company),totalMoney=(Number(t.pay)||0)+(Number(t.fuelAllowance)||0)+specialBonus;recordCompanyContractDelivery(t.company,at);addSystemMessage('Entrega concluída em '+t.to,'A entrega de '+t.cargo+' para '+(t.company||'empresa local')+' foi concluída. Rota: '+t.from+' → '+t.to+'. Você ganhou '+t.xp+' XP e '+money(totalMoney)+'.');state.trip=null;if(specialBonus){state.specialMission=null;ensureSpecialMission(true)}save();clearInterval(mapTimer);toast('Entrega concluída! Você chegou a '+t.to+': +'+t.xp+' XP e '+money(t.pay)+' · combustível '+money(Number(t.fuelAllowance)||0)+(missionReward?' · +'+missionReward+' pontos de missão':'')+(reputationReward?' · reputação '+reputationReward.company+' nível '+reputationReward.level:'')+(specialBonus?' · bônus especial '+money(specialBonus)+' · +'+specialSkillPoints.toFixed(2).replace('.',',')+' ponto de habilidade':'')+' · pneus '+condition.toFixed(1).replace('.',',')+'%.');location.hash='home'}
function newspaperPage(){$('#view').innerHTML=heading('IMPRENSA LONER','Jornal Loner','Acompanhe as notícias que movimentam a economia e as estradas do jogo.')+'<section class="newspaper-page"><header><div><span>EDIÇÃO ATUAL</span><h2>A corrida logística começa em São Paulo</h2><p>Empresas disputam espaço enquanto os jogadores constroem fábricas, produzem cargas e abrem novas rotas pelo estado.</p></div><b>v.0.1.0</b></header><a class="newspaper-sheet" href="assets/newspaper/jornal-loner-v0.1.0.png" target="_blank" rel="noopener" title="Abrir Jornal Loner em tamanho completo"><img src="assets/newspaper/jornal-loner-v0.1.0.png" alt="Página completa do Jornal Loner, edição v.0.1.0"></a><footer><span>CLIQUE NO JORNAL PARA ABRIR EM TAMANHO COMPLETO</span><a href="assets/newspaper/jornal-loner-v0.1.0.png" target="_blank" rel="noopener">LER EDIÇÃO COMPLETA</a></footer></section>'}function versionPage(){$('#view').innerHTML=heading('HISTÓRICO DE DESENVOLVIMENTO','Loner v.0.1.0','Acompanhe as novidades e melhorias adicionadas ao jogo.')+'<section class="release-current"><span>VERSÃO ATUAL</span><h2>v.0.1.0</h2><p>O sistema de investimentos chega ao jogo, acompanhado por novas opções de viagem, empresas e cidades.</p></section><section class="changelog"><article><time>v.0.1.0 · ATUAL</time><h3>Investimentos e evolução da logística</h3><ul><li>Viagens livres agora permitem o deslocamento entre cidades sem uma encomenda ativa, com bônus de 25% na velocidade enquanto o caminhão estiver sem carga.</li><li>Expansão do mapa com São Caetano do Sul, Mogi das Cruzes, Guararema, Jacareí, São José dos Campos, Cotia, Alumínio, Vargem Grande Paulista, Itapecerica da Serra, Itariri, Araçoiaba da Serra, Capela do Alto, Sarapuí, Salto de Pirapora, Pilar do Sul, Salto, Porto Feliz, Boituva, Iperó, Tatuí, Pirapora do Bom Jesus, Araçariguama, Cajamar, Mairinque e Francisco Morato.</li><li>Mercado de fretes ampliado com a inclusão das operações do Mercado Livre e da Amazon.</li><li>Identidade visual, produtos transportados e imagens de carga das empresas Pirelli e Bosch foram atualizados.</li><li>Novo sistema de progressão por empresa, com experiência acumulada individualmente e ranking específico de entregas para cada contratante.</li><li>A aba Mapa recebeu um localizador de cidades, permitindo pesquisar e encontrar destinos com mais rapidez.</li><li>Novo sistema de investimentos, com compra e venda de ações, acompanhamento de valores e pagamento periódico de dividendos.</li></ul></article><article><time>v.0.0.26</time><h3>Missões e mercado dinâmico</h3><ul><li>Missões diárias e semanais aleatórias com pontos próprios e reinícios pelo horário de Brasília.</li><li>Novo ranking de missões e separação das classificações por abas.</li><li>Mercado fictício das principais empresas, influenciado pelas entregas dos jogadores.</li><li>Doze ofertas em cada cidade, divididas em quatro faixas de distância, renovadas à meia-noite e repostas após cada aceite.</li><li>Páginas individuais das empresas com cidades, cargas, distância, duração, pagamento e experiência.</li><li>Sistema de diesel S10 com consumo por quilômetro, abastecimento e auxílio-combustível pago pelas empresas.</li><li>Página Meu caminhão reorganizada em abas de informações básicas, condições do veículo e inventário.</li><li>Volkswagen 8-150 adicionado à concessionária, com suporte à frota própria e troca de veículo ativo.</li></ul></article><article><time>v.0.0.25a–v.0.0.25j</time><h3>Conta, mapa e expansão regional</h3><ul><li>Login Google/Firebase corrigido com perfil, progresso e viagem sincronizados entre dispositivos.</li><li>Botão para sair da conta adicionado ao perfil e relógio de Brasília estabilizado.</li><li>Fotos dos jogadores, cartões da viagem e posição multiplayer aprimorados no mapa.</li><li>Nome da rua ou rodovia atual exibido durante a viagem quando disponível.</li><li>Praia Grande, Mongaguá, Itanhaém, Peruíbe, Juquitiba, Embu das Artes e Miracatu adicionadas com empresas, logos e rotas.</li><li>Página Empresas reorganizada com catálogo, logos e informações completas sem sobreposição.</li></ul></article><article><time>v.0.0.25</time><h3>Viagens multiplayer ao vivo</h3><ul><li>Posição simulada dos jogadores no mapa em tempo real.</li><li>Trajeto rodoviário, foto, tempo e distância restantes.</li><li>Painel ao clicar no motorista com carga, empresa e horário de aceite.</li><li>Sincronização das coordenadas pelo Firebase.</li></ul></article><article><time>v.0.0.24</time><h3>Economia e presença online</h3><ul><li>Nova página Saldo com entradas, saídas e histórico recuperado.</li><li>Ranking por dinheiro, nível e quilômetros percorridos.</li><li>Persistência do progresso entre dispositivos.</li><li>Primeiro sábado isento do aluguel da tia.</li></ul></article><article><time>v.0.0.23</time><h3>Novas cidades e empresas</h3><ul><li>Guarulhos, Cabreúva e São Roque adicionadas ao mapa.</li><li>Novas fábricas, logotipos, cargas e conexões rodoviárias.</li><li>Criação da transportadora própria e controle de frota.</li></ul></article></section>'}
function route(){if(productionBusy)return;updateTripFuel();clearInterval(mapTimer);clearInterval(liveDriversTimer);if(activeMap){activeMap.remove();activeMap=null}if(state?.trip&&!state.trip.pausedAt&&state.trip.end<=Date.now()){finishTrip();return}if(state&&!state.startCityChosen){startCityPage();$('.sidebar').removeClass?.('open');return}const page=location.hash.slice(1)||'home',navPage=page==='perfil/saldo'?'perfil':(page==='agricultura'||page==='farmaceutico'||page==='vinicola'||page==='fabrica-massas')?'galpoes':page==='investimentos'?'banco':page;document.querySelectorAll('[data-page]').forEach(a=>a.classList.toggle('active',a.dataset.page===navPage));if(page==='jornal')newspaperPage();else if(page==='empresas')companiesPage();else if(page==='versao')versionPage();else if(page==='perfil'){profileTab='overview';profile()}else if(page==='perfil/saldo'){profileTab='balance';profile()}else if(page==='missoes')missionsPage();else if(page==='habilidades')skillsPage();else if(page==='galpoes')warehousesPage();else if(page==='agricultura')agriculturePage();else if(page==='farmaceutico')pharmaceuticalPage();else if(page==='vinicola')wineFactoryPage();else if(page==='fabrica-massas')pastaFactoryPage();else if(page==='chamadas')playerCallsPage();else if(page==='mensagens')messagesPage();else if(page==='saldo'){location.replace('#perfil/saldo')}else if(page==='investimentos')investmentsPage();else if(page==='ranking')ranking();else if(page==='caminhao')truckPageV2();else if(page==='concessionaria')truckShop();else if(page==='banco')bankPage();else if(page==='entregas'||page==='empresa/coca-cola')deliveries();else if(page==='previsao')routePreviewPage();else if(page==='mapa')mapPage();else if(page.startsWith('jogador/'))playerPage(decodeURIComponent(page.slice(8)));else if(page.startsWith('cidade/'))cityPage(decodeURIComponent(page.slice(7)));else if(page.startsWith('empresa/'))companyDetailsPage(decodeURIComponent(page.slice(8)));else if(page==='empresa')companyPage();else if(state.trip)tripHome();else home();$('.sidebar').classList.remove('open')}
function brazilNow(){const parts=Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit',weekday:'short',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).formatToParts(new Date()).filter(p=>p.type!=='literal').map(p=>[p.type,p.value]));return parts}
function updateBrazilClock(){const p=brazilNow(),clock=$('#brasil-clock b');if(clock)clock.textContent=p.day+'/'+p.month+'/'+p.year+' · '+p.hour+':'+p.minute+':'+p.second}
function chargeWeeklyRental(){if(!user||!state)return;const p=brazilNow(),today=p.year+'-'+p.month+'-'+p.day;if(p.weekday!=='Sat')return;state.rentalExemptOn=state.rentalExemptOn||firstSaturdayFromAccount();const charges=[];if(state.truck==='tia'&&today!==state.rentalExemptOn&&state.rentalPaidOn!==today&&state.balance>=700){state.balance-=700;state.rentalPaidOn=today;addLedger('debit',700,'Aluguel semanal da tia','Cobrança automática de sábado.',Date.now(),'rental-'+today);charges.push('aluguel da tia: -'+money(700))}if(state.loan?.active&&state.loan.paidOn!==today){const payment=Math.min(state.loan.weekly,state.loan.remainingBalance);state.balance-=payment;state.loan.remainingBalance=Math.max(0,state.loan.remainingBalance-payment);state.loan.remainingWeeks=Math.max(0,state.loan.remainingWeeks-1);state.loan.paidOn=today;if(state.loan.remainingBalance<=0||state.loan.remainingWeeks<=0)state.loan.active=false;addLedger('debit',payment,'Parcela do banco','Pagamento semanal do empréstimo.',Date.now(),'loan-payment-'+today);charges.push('parcela do banco: -'+money(payment))}if(!charges.length)return;save();toast('Débito de sábado · '+charges.join(' · ')+'.')}
async function enter(u){user=u;state=await restoreProgress();normalizeGameState();if(state.startCityChosen==null)state.startCityChosen=Boolean(state.savedAt||state.deliveries||state.xp||state.km||(state.history||[]).length);ensureMissions();ensureSpecialMission();localStorage.setItem(key(),JSON.stringify(state));await syncProgress();$('#login').classList.add('hidden');$('#app').classList.remove('hidden');if(!document.querySelector('.sidebar-version')){const versionLink=document.createElement('a');versionLink.href='#versao';versionLink.dataset.page='versao';versionLink.className='sidebar-version';versionLink.innerHTML='<span>VERSÃO DO JOGO</span><b>v.0.1.0</b>';document.querySelector('.sidebar-newspaper').insertAdjacentElement('afterend',versionLink)}document.querySelector('[data-page="mapa"]').lastChild.textContent='Mapa';applyRentalExemption();ensureInvestmentState();ensureCompanyContractState();settleCompanyContract(true);payWeeklyDividends();chrome();syncProgress();watchProgress();watchPresence();watchMessages();watchPlayerCalls();watchFarmEarnings();watchGameMarket();watchGlobalOffers();advanceAllFarms();advanceMedicineFactories();advanceWineFactories();advancePastaFactory();retryProductionPublications();route();updateBrazilClock();chargeWeeklyRental();clearInterval(rentalTimer);rentalTimer=setInterval(()=>{updateBrazilClock();if(productionBusy)return;updateOfferClock();payWeeklyDividends();chargeWeeklyRental();settleCompanyContract(true);advanceWineFactories();advancePastaFactory();advanceAllFarms();advanceMedicineFactories();if(Date.now()-productionRetryAt>30000){productionRetryAt=Date.now();retryProductionPublications();watchFarmEarnings()}if(offersDay!==offerCycleKey())watchGlobalOffers();let refreshMissions=ensureMissions();if(ensureSpecialMission())refreshMissions=true;if(refreshMissions){save();if(location.hash==='#missoes')missionsPage()}},1000);document.body.classList.remove('auth-pending')}
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>t.classList.remove('show'),4200)}
async function logout(){try{await syncProgress();await signOut(auth)}catch(error){console.warn('Falha ao sair:',error.code||error.message);toast('Não foi possível sair da conta agora.')}}$('#google-login').onclick=async()=>{try{await setPersistence(auth,browserLocalPersistence);$('#auth-message').textContent='Abrindo o login seguro do Google...';await signInWithPopup(auth,provider)}catch(error){console.warn('Falha no login:',error.code||error.message);const blocked=error.code==='auth/popup-blocked',closed=error.code==='auth/popup-closed-by-user';$('#auth-message').textContent=blocked?'Permita a janela de login do Google e tente novamente.':closed?'Login cancelado. Tente novamente quando quiser.':'Não foi possível entrar. Verifique a conexão e tente novamente.'}};$('#profile-shortcut').onclick=()=>location.hash='perfil';$('#top-message-shortcut').onclick=()=>location.hash='mensagens';$('#menu-toggle').onclick=()=>$('.sidebar').classList.toggle('open');addEventListener('hashchange',route);updateBrazilClock();clearInterval(clockTimer);clockTimer=setInterval(updateBrazilClock,1000);onAuthStateChanged(auth,u=>{if(u)enter(u).catch(error=>{console.error('Falha ao carregar a conta:',error);$('#auth-message').textContent='Sua conta entrou, mas o perfil não pôde ser carregado. Atualize a página.';document.body.classList.remove('auth-pending')});else{progressStop?.();presenceStop?.();messagesStop?.();playerCallsStop?.();farmEarningsStop?.();marketStop?.();offerStateStop?.();clearInterval(presenceTimer);clearInterval(rentalTimer);user=null;state=null;$('#app').classList.add('hidden');$('#login').classList.remove('hidden');$('#auth-message').textContent='';document.body.classList.remove('auth-pending')}});

// Production sites are distinct destinations connected to the road network.
function productionSite(product,city){
 if(product==='pasta')return{product,city:'Campinas',point:PASTA_FACTORY_SITE,page:'fabrica-massas',name:'Fábrica Artesanal de Massas'};
 if(product==='wine')return{product,city:'São Roque',point:WINE_FACTORY_SITE,page:'vinicola',name:'Fábrica de Vinho'};
 if(product==='paracetamol')return{product,city,point:MEDICINE_FACTORY_SITES[city],page:'farmaceutico',name:'Fábrica de Medicamentos'};
 return{product:'player-rice',city,point:RICE_FARM_SITES[city],page:'agricultura',name:'Plantação de Arroz'};
}
function atProductionSite(product,city){return !state.trip&&state.city===city&&state.facility?.product===productionSite(product,city).product&&state.facility?.city===city}
function productionSites(){return[productionSite('pasta','Campinas'),productionSite('wine','São Roque'),...Object.keys(RICE_FARM_SITES).map(c=>productionSite('player-rice',c)),...Object.keys(MEDICINE_FACTORY_SITES).map(c=>productionSite('paracetamol',c))]}
function drawProductionRoads(){if(!activeMap)return;for(const site of productionSites()){const city=cities[site.city];if(!city||!site.point)continue;L.polyline([[city.lat,city.lng],[site.point.lat,city.lng],[site.point.lat,site.point.lng]],{color:'#e4b86b',weight:4,opacity:.85}).addTo(activeMap).bindTooltip('Acesso à '+site.name).on('click',()=>{farmViewCity=site.city;location.hash=site.page})}}
async function startProductionAccess(product,city,button){
 if(state.trip)return;const site=productionSite(product,city);
 if(state.city!==site.city){location.hash='cidade/'+encodeURIComponent(site.city);return}
 if(atProductionSite(product,city))return;
 if(!site.point||tireCondition()<=0||fuelLevel()<=0){toast('Verifique os pneus e abasteça antes de acessar a empresa.');return}
 button.disabled=true;
 const start=state.facility?productionSite(state.facility.product,city).point:cities[city],end=site.point;
 let path=[[start.lat,start.lng],[end.lat,start.lng],[end.lat,end.lng]],km=Math.max(1,Math.round(Math.hypot((end.lat-start.lat)*111,(end.lng-start.lng)*102)*1.3));
 try{const response=await fetch('https://router.project-osrm.org/route/v1/driving/'+start.lng+','+start.lat+';'+end.lng+','+end.lat+'?overview=full&geometries=geojson', {signal:AbortSignal.timeout(8000)}),data=await response.json();if(data.routes?.[0]){path=data.routes[0].geometry.coordinates.map(p=>[p[1],p[0]]);km=Math.max(1,Math.round(data.routes[0].distance/1000))}}catch{}
 if(state.trip||state.city!==city)return;
 if(km>currentTruck().range){button.disabled=false;toast('Alcance insuficiente para chegar à empresa.');return}
 const now=Date.now();state.trip={freeTrip:true,facilityArrival:{product:site.product,city},truckId:state.truck,from:city,to:city,company:site.name,cargo:truckPalletCount()+' paletes no caminhão',path,totalKm:km,start:now,end:now+Math.max(1,travelMinutes(km))*60000,fuelStart:fuelLevel(),fuelPlanned:fuelLitersFor(km),fuelUsed:0,pay:0,xp:0};state.facility=null;save();location.hash='mapa';
}
function renderProductionAccess(product,city){
 const site=productionSite(product,city),here=atProductionSite(product,city),calls=playerCalls.filter(c=>c.status==='available'&&c.product===product&&c.origin===city);
 const panel=document.createElement('section');panel.className='production-access';
 panel.innerHTML='<div><span>ACESSO RODOVIÁRIO À EMPRESA</span><h2>'+escapeHTML(site.name)+'</h2><p>'+escapeHTML(city)+' → estrada de acesso → pátio da empresa</p><button data-access-production '+(state.trip||here?'disabled':'')+'>'+(here?'VOCÊ ESTÁ NO PÁTIO':state.trip?'VIAGEM EM ANDAMENTO':state.city===city?'SEGUIR CAMINHO ATÉ A EMPRESA':'VIAJAR ATÉ '+escapeHTML(city.toUpperCase()))+'</button></div><div class="production-public-stock"><h3>PALETES DISPONÍVEIS PARA RETIRADA</h3>'+calls.map(call=>'<article><div><b>'+escapeHTML(call.ownerName)+'</b><p>'+escapeHTML(call.ownerCompany||site.name)+' · Destino: '+escapeHTML(call.destination)+'</p><small>Frete: '+money(call.ownerId===user.uid?call.gross:500+fuelCostFor(call.km))+'</small></div><button data-production-pickup="'+escapeHTML(call.id)+'" '+(!here||truckPalletCount()>=truckPalletLimit()?'disabled':'')+'>RETIRAR PALETE</button></article>').join('')+(!calls.length?'<p>Nenhum palete publicado para retirada neste local.</p>':'')+'</div>';
 const ownedCalls=calls.filter(c=>c.ownerId===user.uid);document.querySelectorAll('.pallet-slot.occupied').forEach((slot,index)=>{const call=ownedCalls[index];if(!call)return;const button=document.createElement('button');button.textContent='RETIRAR PALETE';button.disabled=!here||truckPalletCount()>=truckPalletLimit();button.onclick=()=>claimPlayerCall(call.id,button);slot.append(button)});
 $('#view').append(panel);panel.querySelector('[data-access-production]').onclick=e=>startProductionAccess(product,city,e.currentTarget);panel.querySelectorAll('[data-production-pickup]').forEach(b=>b.onclick=()=>claimPlayerCall(b.dataset.productionPickup,b));
}
function refreshProductionPage(){const page=location.hash;if(!['#agricultura','#farmaceutico','#vinicola','#fabrica-massas'].includes(page))return;clearInterval(mapTimer);if(page==='#agricultura')agriculturePage();else if(page==='#farmaceutico')pharmaceuticalPage();else if(page==='#vinicola')wineFactoryPage();else if(page==='#fabrica-massas')pastaFactoryPage()}
const productionPublishing=new Set();
async function publishProductionCall(id,payload){if(productionPublishing.has(id))return;productionPublishing.add(id);try{await runTransaction(db,async tx=>{const ref=doc(db,'playerCalls',id),snap=await tx.get(ref);if(!snap.exists())tx.set(ref,payload)})}finally{productionPublishing.delete(id)}}
function retryProductionPublications(){
 const missing=p=>!playerCalls.some(c=>c.id===p.id)&&!productionPublishing.has(p.id);
 ensurePastaFactoryState().stock.filter(missing).forEach(publishPastaCall);
 Object.entries(ensureAgricultureState().farms).forEach(([city,f])=>(f.stock||[]).filter(missing).forEach(p=>publishRiceCall(city,p)));
 Object.entries(ensurePharmaceuticalState().factories).forEach(([city,f])=>(f.stock||[]).filter(missing).forEach(p=>publishMedicineCall(city,p)));
 (ensureWineState()['São Roque']?.stock||[]).filter(missing).forEach(publishWineCall);
}
function productionCargo(call){return{id:call.id,product:call.product,name:({pasta:'Palete de massas',wine:'Palete de vinho',paracetamol:'Palete de paracetamol'})[call.product]||'Palete de arroz',contract:{...call,fuelAllowance:Number(call.fuelAllowance)||0}}}
function recoverClaimedProduction(){if(productionBusy)return;let changed=false;for(const call of playerCalls){if(call.status==='claimed'&&call.claimedBy===user.uid&&!state.truckPallets.some(p=>p.id===call.id)){state.truckPallets.push(productionCargo(call));changed=true}}if(changed)save()}
let productionBusy=false,productionRetryAt=0;
function renderProductionDelivery(city){
 const pallets=state.truckPallets.filter(p=>p.contract?.destination===city);if(!pallets.length)return;
 const panel=document.createElement('section');panel.className='production-access';panel.innerHTML='<h2>Entrega de produção</h2><p>'+pallets.length+' palete(s) com destino a '+escapeHTML(city)+'. Confirme a entrega para concluir o contrato e receber o pagamento.</p><button data-deliver-production '+(state.trip||state.city!==city||state.facility?'disabled':'')+'>ENTREGAR PALETES</button>';$('#view').append(panel);panel.querySelector('button').onclick=e=>completeProductionContracts(e.currentTarget);
}
async function completeProductionContracts(button){
 if(productionBusy||state.trip||state.facility)return;productionBusy=true;if(button)button.disabled=true;
 try{await syncProgress();const ids=state.truckPallets.filter(p=>p.contract?.destination===state.city).map(p=>p.id);let total=0;
 for(const id of ids){const result=await runTransaction(db,async tx=>{
  const callRef=doc(db,'playerCalls',id),progressRef=doc(db,'progress',user.uid),callSnap=await tx.get(callRef),progressSnap=await tx.get(progressRef);
  if(!callSnap.exists())throw Error('Chamada não encontrada.');const call=callSnap.data(),saved=progressSnap.data();
  if(call.status!=='claimed'||call.claimedBy!==user.uid||call.destination!==state.city)throw Error('Este palete não está disponível para entrega.');
  if(!saved.truckPallets?.some(p=>p.id===id))throw Error('Palete ausente no caminhão.');
  const own=call.ownerId===user.uid,pay=own?call.gross:500+(Number(call.fuelAllowance)||0),at=Date.now();
  const next={...saved,truckPallets:saved.truckPallets.filter(p=>p.id!==id),balance:saved.balance+pay,savedAt:at,ledger:[{id:'production-delivery-'+id,type:'credit',amount:pay,title:'Entrega de produção',details:call.origin+' → '+call.destination,ref:'production-delivery-'+id,at},...(saved.ledger||[])]};
  tx.update(callRef,{status:'delivered',deliveredBy:user.uid,deliveredByName:user.displayName||'Motorista',deliveredAt:serverTimestamp(),deliveredAtMs:at});
  if(!own)tx.set(doc(db,'farmEarnings',id+'-'+call.ownerId),{id:id+'-'+call.ownerId,ownerId:call.ownerId,courierId:user.uid,callId:id,amount:Math.max(0,call.gross-500-(Number(call.fuelAllowance)||0)),courierName:user.displayName||'Motorista',destination:call.destination,product:call.product,claimed:false,createdAt:serverTimestamp(),createdAtMs:at});
  tx.set(progressRef,next);return{next,pay};
 });state={...state,...result.next};total+=result.pay;localStorage.setItem(key(),JSON.stringify(state))}
 chrome();syncPresence();toast('Entrega concluída! Você recebeu '+money(total)+'.');cityPage(state.city);
 }catch(error){console.warn('Entrega pendente:',error);toast('Não foi possível concluir a entrega. O palete permanece no caminhão; tente novamente.');if(button)button.disabled=false}finally{productionBusy=false}
}

function drawCompanyRoads(){
 if(!activeMap)return;
 const group=L.layerGroup(),sites=[];
 Object.entries(factoryData).forEach(([city,factories])=>{const center=cities[city];if(!center)return;factories.forEach((factory,index)=>{const angle=index*2.399,point=[center.lat+Math.cos(angle)*.025,center.lng+Math.sin(angle)*.035];sites.push({city,code:factory.code,point});L.polyline([[center.lat,center.lng],[point[0],center.lng],point],{color:'#82969a',weight:3,opacity:.75}).addTo(group).bindTooltip('Caminho até '+factory.name);const icon=L.divIcon({className:'company-road-marker',html:'<span>'+escapeHTML(factory.code)+'</span>',iconSize:[28,28],iconAnchor:[14,14]});L.marker(point,{icon,title:factory.name+' · '+city}).addTo(group).bindTooltip(escapeHTML(factory.name)).on('click',()=>location.hash='empresa/'+factory.code)})});
 const update=()=>{if(activeMap.getZoom()>=9){if(!activeMap.hasLayer(group))group.addTo(activeMap)}else if(activeMap.hasLayer(group))group.remove()};activeMap.on('zoomend',update);update();
 try{const selected=JSON.parse(sessionStorage.getItem('loner-company-map')||'null'),site=sites.find(s=>s.city===selected?.city&&s.code===selected?.code);if(site){sessionStorage.removeItem('loner-company-map');activeMap.setView(site.point,12);update()}}catch{}
}
